{
  "name": "opencode-commandcode-provider-go",
  "version": "0.4.2",
  "author": "Brent Weatherall",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/dylansalim3/opencode-commandcode-provider.git"
  },
  "main": "dist/index.js",
  "devDependencies": {
    "@types/node": "^25.9.1",
    "ai": "6.0.191",
    "typescript": "^6.0.3"
  },
  "exports": {
    ".": {
      "import": "./dist/index.js"
    },
    "./server": {
      "import": "./dist/plugin.js"
    }
  },
  "bugs": {
    "url": "https://github.com/dylansalim3/opencode-commandcode-provider/issues"
  },
  "description": "Command Code API provider for opencode — use open-source models (DeepSeek, Qwen, Kimi, GLM, MiniMax, Step, Gemini) via Command Code",
  "engines": {
    "bun": ">=1.0.0"
  },
  "files": [
    "dist",
    "models.json"
  ],
  "homepage": "https://github.com/dylansalim3/opencode-commandcode-provider#readme",
  "keywords": [
    "opencode",
    "opencode-provider",
    "opencode-plugin",
    "commandcode",
    "ai",
    "llm",
    "open-source",
    "deepseek",
    "qwen",
    "kimi",
    "glm",
    "minimax",
    "gemini"
  ],
  "license": "MIT",
  "scripts": {
    "test": "bun test tests/unit/",
    "test:integration": "bun test tests/integration/",
    "test:all": "bun test",
    "typecheck": "tsc --noEmit",
    "build": "tsc && node -e \"require('fs').copyFileSync('models.json','dist/models.json')\"",
    "generate-readme": "bun run scripts/generate-readme.ts",
    "sync": "bun run scripts/sync-models.ts",
    "sync:global": "bun run scripts/sync-models.ts --update-global"
  },
  "type": "module",
  "types": "dist/index.d.ts",
  "peerDependencies": {
    "ai": ">=6.0.0"
  }
}
